new_urls=[]
for d in TX3_COUNTIES:
    sources=[
        ('Texas Commission on Environmental Quality — Getting a Permit for an OSSF',TX3_STATE),
        ('Texas Commission on Environmental Quality — OSSF Licensing',TX3_LICENSES),
    ] + d['sources']
    sections=[
        ('Texas permitting framework','Texas requires a permit and approved plan to construct, install, alter, extend, or repair an OSSF unless a specific exemption applies. TCEQ directs owners to the local permitting authority where an authorized local program exists and warns that local programs can be more stringent than statewide minimums.'),
        ('Licensed OSSF professionals','TCEQ licenses or registers site evaluators, installers, maintenance providers, maintenance technicians, and designated representatives. County procedures can require particular licensed professionals based on system type, site conditions, and local rules.')
    ] + d['sections']
    new_urls.append(write_county_page('Texas','texas',d['county'],d['authority'],d['contact'],sections,sources,verified='August 29, 2026'))

sitemap=OUTPUT/'sitemap.xml'
